  "upgrade.intro": "Sabbin abokan ciniki masu cancanta za su iya samun gwaji ɗaya na kwana {days} a kowane asusu, ba gwaji ɗaya a kowane tsari ba. Canzawa daga Essentials zuwa Business ba ya fara wani gwaji kyauta. Kana kan",
