  "upgrade.dialogUpgradeDesc": "Gwajinka da biyan kuɗinka suna nan a kan biyan kuɗi ɗaya — babu biyan kuɗi na biyu, babu sabon gwaji.",
  "upgrade.dialogDowngradeDesc": "Saukawa ba ta taɓa share bayanan ka ba — amma wasu daga cikinsu sun zama marasa shiga. Karanta wannan da farko.",
