  "upgrade.reviewPeriod": ".",
  "upgrade.upgradeNeverRestartsTrial": "Haɓakawa ba ta taɓa sake fara gwajinka kyauta ba.",
  "upgrade.trialHistoryNote": "Idan kana biyan Essentials ka koma Business, kana riƙe asusun abokin ciniki ɗaya da tarihin gwaji. Business ba ta haɗa da ƙarin gwaji na kwana bakwai ba. Idan ka haɓaka yayin da gwajinka na asali yana gudana, ranar ƙarshensa ta asali ba ta sake saitawa.",
  "upgrade.providerConfirmNote": "Canjin tsari yana buƙatar tabbatarwa daga mai bayar da biyan kuɗi. Dole ne a nuna duk bambancin farashi, ragi, da ranar fara aiki kafin ka amince da canjin. Haɓakawa dole ne kada ta ƙirƙiri biyan kuɗi na biyu a lokaci ɗaya.",
  "upgrade.chargedThroughProviderNote": "Ana caji canjin tsari ta hanyar mai bayar da biyan kuɗi. Za ka iya soke biyan kuɗinka daga wannan shafi ta amfani da maɓallin Soke Biyan Kuɗi a ƙarƙashin tsarinka na yanzu, ko daga Saituna. Sokewa yana dakatar da sabuntawa na gaba a ƙarshen lokacin biyanka; ba ya ƙare shigarka nan take. Ba a caji wuraren aiki kyauta da ke akwai don duba waɗannan zaɓuɓɓuka.",
