  "billing.cancel.refundWindowOpen": "Ka soke cikin kwana 3 na cajin biyan ka na farko, don haka za ka iya cancanta don maidowa na wannan biyan na farko. Sokewa da kansa ba ta bayar da maidowa ba — nemi ta ta hanyar {contact}.",
  "billing.cancel.refundWindowClosed": "Sokewa da kanta ba ta bayar da maidowa ba. Maidowa tana aiki ne kawai cikin kwana 3 na cajin biyan farko da ya yi nasara, ana nema ta hanyar {contact}.",
