  "billing.dryRun.title": "Essentials → Business — kwaikwayon aiki",
  "billing.dryRun.body": "Yi aikin ƙa'idodin haɓaka da aka gabatar ta amfani da bayanan almara gaba ɗaya a wannan burauza. Wannan ba ya karanta ko canza samfurin TEST — Pajama Pants ɗinka na ainihi, wurin aikin Business ɗinka na yanzu, Stripe, gwaje-gwaje, biyan kuɗi ko kaya.",
  "billing.dryRun.runButton": "Gudanar da kwaikwayon haɓaka na gida (babu caji)",
