  "exports.eyebrow": "Bayani",
  "exports.title": "Fitarwa da madadin",
  "exports.subtitleStart": "Ana iyakance saukewa koyaushe zuwa",
  "exports.subtitleRest": ". Kowane fayil ana yi wa alama da sunan kasuwanci da ranar da aka yi shi.",
  "exports.createBusinessFirst": "Ƙirƙiri kasuwanci da farko — fitarwa na kasuwanci ne, ba na manhaja ba.",
  "exports.lockedTitle": "Fitarwa ta CSV da Excel fasali ne na Business",
  "exports.lockedDesc": "Wurin aikinka yana kan tsarin Essentials. Business yana ƙara fitarwa ta CSV da Excel, ƙimar kaya, samfura da ma'aikata marasa iyaka, masu samarwa, sayayya da bundles.",
  "exports.seeBusiness": "Duba abin da Business ya haɗa",
  "exports.whatTheseAre": "Abin da waɗannan fayiloli suke",
  "exports.about1": "Kowane saitin bayanai yana zuwa a matsayin CSV ko littafin aikin Excel na ainihi (.xlsx) — cikakken littafin aikin kaya Excel kaɗai ne, tare da takarda ɗaya a kowane saitin bayanai. Fayilolin CSV suna buɗewa a Excel, Numbers, Google Sheets da yawancin manhajojin kaya. Ana kiyaye rubutun UTF-8, waƙafi da aka yi wa alama, karyewar layi a bayanan kula da sifili na farko a lambobi, kuma ana kawar da sel da suka fara kamar dabara don haka spreadsheet ta buɗe su a matsayin rubutu.",
  "exports.about2": "A cikin fayilolin Excel, SKU, UPC, ISBN da barcode sel ne na rubutu — ba a taɓa rubutun kimiyya ba kuma ba a taɓa yanke sifili ba — tare da faɗin ginshiƙi, tace kanun labarai da tsarin kuɗi ko yawa da aka yi amfani da su. Cikakken littafin aikin kaya yana riƙe samfura, matakan kaya, wurare da motsi a takardu daban-daban.",
  "exports.about3": "Fitarwa mai girma sosai tana tsayawa a layuka 20,000 a kowane saitin bayanai — lokacin da hakan ya faru sunan fayil yana faɗin haka (truncated-20000), don haka fayil ɗin da bai cika ba ba zai taɓa wucewa a matsayin cikakke ba.",
  "exports.about4": "Madadin hoton bayanan ka ne, ba dawo da sau ɗaya ba. Dawo da shi aiki ne na hannu, da duba da farko, don haka ka riƙe fayil ɗin lafiya — babu abin da a cikin manhaja zai iya sake ƙirƙirar kasuwancin da aka share daga gare shi tukuna. Ana kula da lambar manhaja da madadin dandalin Base44 daban da waɗannan fayiloli.",
  "exports.about5": "Ana lissafa hotuna da abubuwan da aka haɗa a matsayin hanyoyin da aka adana su — ba a haɗa fayilolin hoton da kansu a cikin saukewa ba.",
  "exports.backupTitle": "Cikakken madadin",
  "exports.backupDesc": "Fayil ɗaya da samfuran wannan kasuwanci, wurare, matakan kaya, cikakken littafin motsi, masu samarwa, sayayya, oda, maidowa, ƙidaya da jeri — tare da saitunan bayanin sa. Ajiye shi a wani wuri da kake sarrafawa.",
  "exports.backupIncludes1": "Samfura, lambobi, farashin saya da bayanan kula",
  "exports.backupIncludes2": "Wurare da yawa na kowane wuri",
  "exports.backupIncludes3": "Kowane motsi, tare da wanda ya yi shi da lokaci",
  "exports.backupIncludes4": "Sayayya, oda, maidowa da ƙidaya",
