  "import.createDesc": "yana ƙara layukan da ba su cikin katalogi ba tukuna. Ana tsallake SKU da barcode da aka kwafi da aka riga aka yi amfani da su, kuma ana iya sanya kayan buɗewa a wurin da ka zaɓa a matsayin karɓa.",
  "import.updateTitle": "Sabunta samfuran da ke akwai",
  "import.updateDesc": "yana daidaita kowane layi ta SKU ko ID na rikodi kuma yana nuna tsohuwar ƙima kusa da sabuwar da aka gabatar. Sel marasa komai suna barin ƙimar da aka adana kamar yadda take sai dai idan ka nemi a share marasa komai, kuma ba a taɓa taɓa yawa ba.",
  "import.receiveModeTitle": "Karɓi kaya",
  "import.receiveModeDesc": "yana ƙara yawan da ya iso zuwa wuri ɗaya kuma yana rubuta karɓa a littafin motsi ga kowane layi. Ana yi wa kowane rukuni alama, don haka ba a iya karɓar takarda ɗaya sau biyu.",
  "import.excelNote": "Ana karanta littattafan aikin Excel (.xlsx) kai tsaye — zaɓi takardar aiki kuma ana daidaita ginshiƙai a gare ka. Lambobi suna nan gaba ɗaya: UPC da aka adana a matsayin rubutu yana riƙe lambobinsa da sifili na farko. Ana lissafa layukan da ba a iya shigar da su ba tare da dalili",
