  "reports.movementsCapped": "An karanta shigar littafi {cap} na baya-bayan nan kaɗai, don haka motsi da suka girmi waɗannan ba sa cikin jimillolin. Taƙaita lokacin don ganin ainihin adadi na taga.",
  "reports.footnote": "Tallace-tallace suna amfani da farashin siyarwa na yanzu na kowane samfur, karɓa suna amfani da farashin saya da aka rubuta lokacin da kaya ya iso, kuma asara suna amfani da farashin saya na raka'a na yanzu. Kuɗin da ya ɓace ba a taɓa ɗaukarsa a matsayin sifili ba — bar fili ba komai har sai an san adadin. Rahoto ra'ayi ne, ba takarda ba: ba a rubuta komai a bayanan ka lokacin da ka gudanar da shi.",
