  "valuation.footnote": "Ƙimar farashin saya tana amfani da farashin saya na raka'a na yanzu na kowane samfur, don haka karɓa a sabon farashi yana sake ƙima dukan shago. Raka'an da aka riƙe har yanzu ana ƙidaya su a nan — suna hannu, an yi musu alƙawari ga oda kawai. Kuɗin da ya ɓace ba a taɓa ɗaukarsa a matsayin sifili ba; bar fili ba komai har sai an san adadin.",
