  "print.clearSelection": "Share zaɓi",
  "print.templateIsBusiness": "{label} fasali ne na Business",
  "print.supplierBlockedDesc": "Takardun masu samarwa suna tare da tsarin Business — masu samarwa, sayayya da odar sayayya. Duk abin da kake da shi yanzu yana ci gaba da aiki.",
  "print.seeBusiness": "Duba abin da Business ya haɗa",
  "print.nothingToPrint": "Babu abin da za a buga tukuna",
  "print.pickOrderHint": "Zaɓi odar sayayya daga jerin don samfoti takarda.",
  "print.pickCustomerOrderHint": "Zaɓi odar abokin ciniki daga jerin don samfoti takarda.",
  "print.pickReturnHint": "Zaɓi maidowa da aka rubuta daga jerin don samfoti takarda.",
  "print.chooseStyleHint": "Zaɓi salo, sannan ka zaɓi samfura daga jerin. Samfotin yana nuna ainihin abin da ke fitowa daga firinta.",
  "print.howToReach": "Yadda za a isa ga firintarka",
  "print.howIntro": "Wannan manhaja tana haɗawa da firintocin da kake da su — ba firinta ba ce da kanta. Akwai hanyoyi huɗu don isa ga ɗaya, kuma alamu suna buga a tsare-tsare biyu ta kowace hanya. Takardun shiryawa, odar sayayya, takardun masu samarwa da rahotanni na Business kaɗai ne, duk haɗin da aka yi amfani da shi.",
  "print.howBluetoothLead": "Bluetooth.",
  "print.howBluetoothBody": "Daga wannan shafi, a Chrome ko Edge na tebur da kuma a Chrome na Android: zaɓi firintar alamarka kuma alamu suna zuwa gare ta kai tsaye. Ba ya aiki a Safari na iOS — a iPhone, buga ta Bluetooth yana zuwa tare da manhajar waya maimakon haka. Firinta da ke magana Zebra ZPL kaɗai ko harshen Brother kaɗai ba za ta fahimci alamun da wannan shafi ke aikawa ba; ana duba hakan da firintoci na ainihi kafin a kira shi yana aiki.",
  "print.howWifiLead": "Wi-Fi.",
  "print.howWifiBody": "Shigar da firinta a Wi-Fi na shagonka, sannan ka yi amfani da maɓallin Buga — yana buga ta firintar da aka shigar a wannan kwamfuta, ta hanyar cibiyar shago. A iPhone, AirPrint yana ciki: firintar AirPrint a Wi-Fi ɗaya tana bayyana a takardar buga, ba tare da igiya ko manhaja ba, kuma manhajar ba ta buƙatar lambar musamman ta AirPrint. Firinta dole ne ta tallafa wa AirPrint (yawancin sababbi suna yi) kuma waya da firinta dole ne su kasance a Wi-Fi ɗaya.",
  "print.howEthernetLead": "Ethernet.",
  "print.howEthernetBody": "Haɗa firinta zuwa cibiyar shagonka da igiyar Ethernet, shigar da ita a kwamfuta, ka buga ta maɓallin Buga. Ethernet hanya ce ta tebur da kwamfuta — iPhone ba sa amfani da igiyoyin Ethernet.",
  "print.howUsbLead": "USB.",
  "print.howUsbBody": "Toshe firinta a kwamfuta da igiyarta ka yi amfani da maɓallin Buga — yana buga ta firintar da aka shigar a can. A wayar Android da kebul na USB OTG, maɓallin USB da ke sama yana magana kai tsaye da firinta. iPhone ba za su iya buga ta USB kai tsaye ba — babu WebUSB a can — don haka yi amfani da Wi-Fi / AirPrint, ko Bluetooth daga manhajar waya.",
  "print.howCordsLead": "Igiyoyi har yanzu suna hidima ga iPhone, mataki ɗaya a baya.",
  "print.howCordsBody": "Firintar USB da aka toshe a kwamfutar shago, ko firintar Ethernet da aka haɗa da cibiyar, tana bayyana a iPhone ɗinka ta Wi-Fi na shago (AirPrint / firinta da aka raba) — igiyoyi suna sanya firinta a cibiyar sosai, kuma waya tana isa gare ta ba tare da waya ba.",
  "print.howOfflineLead": "Idan intanet ya faɗi,",
  "print.howOfflineBody": "alamu da takardun da ke wannan shafi har yanzu suna buga — maɓallin Buga, PDF na Alamu, Bluetooth da USB ba sa buƙatar haɗi. Abin da ke buƙatar intanet shi ne loda shafi da samfuransa da farko. Cikakken yanayin layi (aiki a cikin manhaja ba tare da haɗi ba kwata-kwata) gini ne daban, mai girma kuma ba a yi iƙirarin an yi shi a nan ba.",
