  "settings.cancelSubscription": "Soke Biyan Kuɗi",
  "settings.cancelTerms.appleLink": "Umarnin sokewa na Apple",
  "settings.cancelTerms.googlePlayLink": "Umarnin sokewa na Google Play",
  "settings.cancelTerms.graceTitle": "Bayan lokacin biyanka ya ƙare — alheri na kwana 15, sannan sharewa:",
  "settings.cancelTerms.intro": "Waɗannan su ne sharuɗɗan biyan kuɗi na Luminous StockHaven da aka biya. Ana biyan biyan kuɗi na yanar gizo ta Stripe. Za ka iya soke biyan kuɗinka da kanka a kowane lokaci ta amfani da maɓallin Soke Biyan Kuɗi da ke ƙasa — ba a buƙatar amincewar ma'aikata. Ana iya kula da buƙatun sokewa da maidowa ta hanyar tuntuɓar tallafin abokin ciniki na hukuma, theluminousbookshop@outlook.com.",
  "settings.cancelTerms.noApprovalBody": "Za ka iya soke biyan kuɗinka da kanka a kowane lokaci. Ba a buƙatar amincewar ma'aikata. Sabuntawa na gaba suna tsayawa ne kawai bayan mai bayar da biyan kuɗi ya tabbatar da sokewa.",
  "settings.cancelTerms.noApprovalTitle": "Soke ba tare da amincewa ba:",
  "settings.cancelTerms.paymentBody": "Don gwaje-gwajen da aka biya, gwajin kwana bakwai yana buƙatar hanyar biya a lokacin rajista. Sai dai idan an soke shi cikin lokacin sokewar gwaji da ya dace, za a caji tsarin wata da aka zaɓa ta atomatik bayan gwaji. Dole ne a nuna farashi, ranar biyan farko, da lokacin sokewa na mai bayarwa yayin rajista. Ana biyan gwaji ta Stripe.",
  "settings.cancelTerms.paymentTitle": "Hanyar biya da sabuntawa ta atomatik:",
  "settings.cancelTerms.remainingBody": "Idan ka riga ka biya lokacin biyan kuɗi, za ka iya riƙe shiga har zuwa ranar da aka tabbatar da biyan ka har zuwa gare ta. Ƙarewa da wuri yana buƙatar tabbatarwa mai dacewa daga mai bayarwa da duk wani kula da maidowa da ya dace. Shigar gwaji kyauta tana ƙarewa bisa ga ranar ƙarewar gwaji da mai bayarwa ya tabbatar.",
  "settings.cancelTerms.remainingTitle": "Shigar da ta rage:",
  "settings.cancelTerms.storesBody": "Idan ka taɓa yin biyan kuɗi ta Google Play ko Apple App Store, shagon ne ke biyan kuɗi da sarrafa biyan kuɗinka. Za ka iya buƙatar soke shi kai tsaye a sashin biyan kuɗi na asusun Google ko Apple ɗaya da aka yi amfani da shi don biyan kuɗi. Soke biyan kuɗi na yanar gizo daban, cire wannan manhaja, ko neman share asusun Luminous StockHaven ba ya soke biyan kuɗi na shago ta atomatik. Duba rasit ɗin sayanka don tabbatar da wanda ke biyan ka.",
  "settings.cancelTerms.storesTitle": "Biyan kuɗi na Google Play da Apple App Store (idan ka taɓa yin biyan kuɗi ta shago):",
  "settings.cancelTerms.title": "Sharuɗɗan Sokewa da Yanayi",
  "settings.cancelTerms.trialBody": "Ana iya amfani da gwajin kwana bakwai sau ɗaya kaɗai ga kowane abokin ciniki mai cancanta. Soke gwaji ko biyan kuɗi ba ya ba da wani gwaji; abokan ciniki da suka dawo dole ne su zaɓi biyan kuɗi da aka biya.",
  "settings.cancelTerms.trialTitle": "Gwaji kyauta ɗaya:",
  "settings.canceled.endsOn": "An soke wannan biyan kuɗi kuma yana ƙare a {date}. Kana riƙe cikakken shiga har zuwa lokacin.",
  "settings.delete.checking": "Ana duba buƙatar sharewa da ke akwai…",
  "settings.delete.description": "Nemi cire asusun shiga na Luminous StockHaven.",
  "settings.delete.dialogDescription": "Wannan yana neman duba share asusu. Ba ya cire shigarka ko kayanka nan take, kuma ba ya soke kowane biyan kuɗi na Stripe. Rubuta {word} don tabbatar da kana son aika buƙatar.",
  "settings.delete.dialogTitle": "Nemi Share Asusu",
  "settings.delete.enterDelete": "Shigar da {word} don tabbatarwa",
  "settings.delete.exportFirst": "Fitar da kayanka da farko idan kana buƙatar riƙe bayanan ka.",
  "settings.delete.intro": "Aika buƙata ba ya share asusunka, kasuwancinka, ko kayanka nan take. Ana duba buƙatu daban kafin a iya kammala sharewa. Wannan buƙata ba ta soke biyan kuɗi na Stripe ko dakatar da biyan kuɗi na gaba; dole ne a kula da sokewar biyan kuɗi daban ta hanyar mai bayar da biyan kuɗi.",
