  "settings.trial.cancelKeeps": "Sokewa yayin gwajinka yana riƙe kwanakin 7 cikakku — shiga ya ƙare a {date}, kuma ba za a caje ka ba.",
  "staff.access.noSeatBody": "Asusunka ba shi da kujerar ma'aikata ga wannan kasuwanci, don haka kayansa suna rufe. Tambayi mai shi ya ƙara ka a Ma'aikata da matsayi.",
  "staff.access.noSeatTitle": "Wannan kasuwanci ba ya buɗe ga shigarka",
  "staff.access.pendingBody": "Wannan kasuwanci yana da gayyata ga imel ɗinka da ba a kunna ba tukuna. Tambayi mai shi ya saita matsayin ma'aikatanka zuwa mai aiki. Babu komai da ake gani a nan har sai lokacin.",
  "staff.access.pendingTitle": "Gayyatarka ba ta aiki ba tukuna",
  "staff.access.signOut": "Fita",
  "staff.access.suspendedBody": "Mai gudanarwa ya dakatar da wannan asusun ma'aikata ga kasuwancin da ke aiki. Tambaye su su mayar da kai zuwa mai aiki, sannan ka sake shiga.",
  "staff.access.suspendedTitle": "An dakatar da shigarka",
  "staff.addFirst": "Ƙara ma'aikaci na farko",
  "staff.addMember": "Ƙara ma'aikaci",
  "staff.emptyBody": "Ƙara mutum, ba shi matsayi da izinin da ke tare da shi, kuma ana gayyatar su ta imel don shiga wannan kasuwanci.",
  "staff.emptyTitle": "Babu ma'aikata tukuna",
  "staff.eyebrow": "Ƙungiya",
  "staff.how.p1": "Kowane memba yana da matsayi da jerin izininsa, don haka za ka iya farawa daga matsayi ka canza abu ɗaya ba tare da yin sabon matsayi ba. Gyara matsayi ba ya sake rubuta membobin da ke kansa — buɗe memba don sake amfani da tsoffin matsayinsa.",
  "staff.how.p2": "Matsayi na musamman fasali ne na Business: Essentials yana amfani da matsayi biyar da aka gina (Mai shi, Manaja, Ma'aikacin kaya, Ma'aikacin tallace-tallace, Mai kallo).",
  "staff.how.p3": "Ana aika gayyata ta imel. Memba zai iya shiga ne kawai da zarar ya karɓa, kuma cire wani daga wannan jeri ba ya share asusun manhajarsa.",
  "staff.how.p4": "Shago shi ne wurin da aka sanya mutum. Ana rubuta shi a katinsa; abin da zai iya buɗewa har yanzu matsayinsa da izininsa ne ke yanke shawara.",
  "staff.how.p5": "Izini yana yanke shawara kan abin da kowane mutum zai iya buɗewa: abubuwan menu da ke waje da matsayinsu ana ɓoye su, kuma adireshin da aka toshe yana nuna sanarwa “ba a kan matsayinka ba” maimakon shafi. Canji yana aiki a lokacin da wannan mutum ya sake loda manhaja; dakatar da memba yana kulle shi gaba ɗaya.",
  "staff.how.p6": "Masu gudanarwa za su iya gani da canza duk bayanai, sarrafa masu amfani da manhaja da matsayi, kuma ba a taɓa iyakance su da matsayin ma'aikata ba. Wani ba tare da rikodin ma'aikata ba — mai sabon kasuwanci — yana riƙe cikakken shiga.",
  "staff.howTitle": "Yadda ma'aikata da matsayi ke aiki",
