  "payroll.dd.savings": "Savings",
  "payroll.dd.steps.body": "1. Kana buƙatar asusun banki na kasuwanci da zai iya aika biyan ACH. 2. Tara fom ɗin izini mai sa hannu daga kowane memban ƙungiya - ceki da aka soke yana taimakawa wajen tabbatar da lambobin. 3. Aika biyan albashi kwanakin kasuwanci 2-3 kafin ranar biya domin kuɗin ya isa a kan lokaci. 4. Yawancin jihohi suna buƙatar izinin rubutu na memban ƙungiya. Wannan manhaja tana tara fom ɗin kuma tana bi da kai cikin matakan - ainihin aika kuɗin yana faruwa ne ta bankinka.",
