  "auth.sameEmailNotice": "Kana da manhajarmu tuni daga Google Play ko App Store? Yi amfani da imel ɗaya a nan — wanda kake shiga manhajar da shi — domin shagonka da kayanka su zo tare da kai. Imel daban yana fara sabon shago mara komai gaba ɗaya.",
  "settings.deleteConfirmWord": "SHARE",
