  "recovery.title": "Mayar da asusunka",
  "recovery.subtitle": "Ka rasa damar shiga imel ɗin da asusunka yake ƙarƙashinsa? Maɓallan ajiyarka za su iya mayar da kai zuwa shagonka.",
  "recovery.remembered": "Ka tuna da shi bayan duka?",
