  "recovery.backupCodeHint": "Lambobin amfani ɗaya da ka ajiye daga Saituna → Tsaro. Kowace lamba tana aiki sau ɗaya kacal.",
  "recovery.useBackupCode": "Yi amfani da lambar ajiyata",
  "recovery.orDivider": "ko",
  "recovery.emailMeCode": "Aika lamba ta imel zuwa imel ɗin ajiyata",
  "recovery.emailMeCodeHint": "Idan ka saita imel ɗin ajiya, za mu aika lambar lambobi 6 a can. Don kare asusunka, wannan shafi koyaushe yana amsawa ta hanya ɗaya — ko an aika lamba ko ba a aika ba.",
  "recovery.codeSent": "Idan imel ɗin ajiyarka yana cikin fayil, lambar lambobi 6 tana kan hanya zuwa can yanzu. Tana ƙarewa cikin minti 10.",
  "recovery.codeLabel": "Lambar lambobi 6",
