  "rewards.title": "Kyaututtuka da ƙarfafawa",
  "rewards.value.giftCard": "Katin kyauta {value}",
  "rewards.value.percentOff": "Ragi {percent}% a shago",
  "rewards.void": "Soke",
  "rewards.voided": "An soke kyauta.",
  "workforce.tab.rewards": "Kyaututtuka",
  "training.lessons.mgr-give-rewards.step1": "Buɗe Ma'aikata ka danna Kyaututtuka. Zaɓi memban ƙungiya, sannan nau'in: kashi na ragi a shago, katin kyauta, ko wani abu daban da ka bayyana a kalmominka.",
  "training.lessons.mgr-give-rewards.step2": "Ba kyautar gajeriyar suna da bayani idan kana so. Mutumin yana samun saƙo nan take, kuma kyautar tana jira a Kyaututtukana tasu tare da lambarta.",
  "training.lessons.mgr-give-rewards.step3": "Iyakar, ta tsari: kana ba da kyauta ga MA'AIKATA kaɗai. Ba za ka iya ba kanka ko wani manaja kyauta ba — ba da kyauta ga manaja hukuncin mai shi ne, kuma manhajar za ta ƙi shi a fili.",
  "training.lessons.mgr-give-rewards.step4": "A til, rubuta lambar da memban ƙungiya ya nuna maka ka yi mata alamar an yi amfani — kowace lamba tana aiki sau ɗaya. Za ka iya soke kyautar da ka bayar idan tsare-tsare suka canza; kyautar mai shi tasu ce da za su soke.",
  "training.lessons.mgr-give-rewards.title": "Ba da kyaututtuka ga ma'aikatanka",
  "training.lessons.owner-give-rewards.step1": "Kyaututtuka suna cikin Ma'aikata, a shafin Kyaututtuka, kuma na tsarin Business ne kaɗai — a Essentials shafin yana nuna ƙofar da aka kulle, domin ƙungiyarka ta ga abin da babban tsarin ke riƙe.",
  "training.lessons.owner-give-rewards.step2": "Za ka iya ba KOWA a ƙungiyar kyauta — ma'aikata da manajoji duka. Zaɓi mutumin, sannan nau'in: kashi na ragi a shago (duk kashi da ka zaɓa), katin kyauta zuwa ko'ina, ko duk ƙarfafawar da ka bayyana a kalmominka.",
  "training.lessons.owner-give-rewards.step3": "Kyautar tana sauka tare da lambarta ta amfani ɗaya kuma tana buga ƙararrawar mutumin. Suna nuna lambar a til; mai shi ko manaja yana rubuta ta don yi mata alamar an yi amfani.",
  "training.lessons.owner-give-rewards.step4": "Takardar kyauta da aka buga ko aka raba tana ɗauke da sunan kasuwancinka KAWAI — ba na manhajar ba. Godiyar shagonka ce, ba talla ba.",
  "training.lessons.owner-give-rewards.title": "Ba da kyaututtuka (tsarin Business)",
  "training.lessons.owner-rewards-oversight.step1": "Manajanka zai iya ba da kyaututtuka ma — ga ma'aikata kaɗai. Manhajar tana ƙin manaja ya ba kansa ko wani manaja kyauta; ba da kyauta ga manaja koyaushe hukuncinka ne.",
  "training.lessons.owner-rewards-oversight.step2": "Kana ganin kowace kyauta a kasuwancin a Tarihin kyaututtuka: wa ya ba da ita, wa ya samu, da ko tana a shirye, an yi amfani ko an soke. Manaja yana ganin kyaututtukan da ya bayar da waɗanda ya karɓa kaɗai.",
  "training.lessons.owner-rewards-oversight.step3": "Za ka iya soke kowace kyauta, ciki har da wadda manajanka ya bayar. Manaja zai iya soke kyaututtukansa, amma ba naka ba.",
  "training.lessons.owner-rewards-oversight.step4": "Kowace lamba tana aiki sau ɗaya kacal, kuma kyautar da aka soke ba za a taɓa amfani da ita ba — tarihi koyaushe yana nuna yadda kyauta ta ƙare.",
  "training.lessons.owner-rewards-oversight.title": "Kula da kyaututtuka: ba da manajanka",
  "training.lessons.staff-your-rewards.step1": "Lokacin da manajanka ko mai shi ya ba ka kyauta, ƙararrawarka tana buga. Buɗe Ma'aikata ka danna Kyaututtuka don ganin ta a Kyaututtukana.",
  "training.lessons.staff-your-rewards.step2": "Kowace kyauta tana da lambarta. Riƙe ta gare ka — duk wanda ya nuna lambar a til shi ne ke amfani da kyautar.",
  "training.lessons.staff-your-rewards.step3": "Don amfani da ita, nuna lambar lokacin da ka saya. Mutumin da ke til yana rubuta ta kuma yana yi mata alamar an yi amfani — kowace lamba tana aiki sau ɗaya kacal.",
  "training.lessons.staff-your-rewards.step4": "Kyaututtuka jin daɗin tsarin Business ne. Idan shagonka ba ya kan Business, shafin Kyaututtuka yana nuna ƙofar da aka kulle maimakon haka — wannan tsarin ne, ba kuskure ba.",
  "training.lessons.staff-your-rewards.title": "Kyaututtukanka: neman lambarka da amfani da ita",
  "training.module.rewards": "Kyaututtuka da ƙarfafawa",
